    private void validerActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_validerActionPerformed
       String log = caselogin.getText();
       String  pass= casepwd.getText();
        if(log.contains("aaaa")&& pass.contains("aaaa")){
                JOptionPane.showMessageDialog(null,"You are connected !");
     }else{
                 JOptionPane.showMessageDialog(null,"Invalid connection !");
        }
      
       
       try {
            String sql = "select * from ihm where login= ? and pwd=? ";
            pst= cnn.prepareStatement(sql);
            pst.setString(1,log);
            pst.setString(2,pass);
            rs = pst.executeQuery();
            if(rs.next()){
                JOptionPane.showMessageDialog(null,"You are connected !");
            }else{
                 JOptionPane.showMessageDialog(null,"Invalid connection !");
            }
            
                
             
             
       }catch (Exception e){
        JOptionPane.showMessageDialog(null, e);
       }
    }//GEN-LAST:event_validerActionPerformed

